/bin/zsh -lc "python -c 'import pandas as pd, numpy as np, json, math
d=pd.read_csv(\"respondents.csv\")
cb=json.load(open(\"codebook.json\"))
v={x[\"name\"]:x.get(\"valid_values\") for x in cb[\"variables\"]}
def dist(g,k):
 q=g[g[k].isin(v[k])];w=q.weight_base
 return [len(g),len(q),round(w.sum(),3),round(w.sum()**2/(w*w).sum(),3),int(g[k].isin([97,98,99]).sum()),int(g[k].isna().sum()),[round(100*w[q[k]==a].sum()/w.sum(),3) for a in v[k]]]
def cell(g,k):
 q=g[(g.followup_status==1)&g[k+\"_pre\"].isin(v[k+\"_pre\"])&g[k+\"_post\"].isin(v[k+\"_post\"])]
 w=q.weight_base.to_numpy(); pre=q[k+\"_pre\"].to_numpy();post=q[k+\"_post\"].to_numpy()
 if k==\"consideration\":pre=(pre>=4)*1;post=(post>=4)*1
 D=post-pre;m=np.sum(w*D)/sum(w);var=len(q)/(len(q)-1)*sum(w*w*(D-m)**2)/sum(w)**2
 return {\"eligible_enrolled\":len(g),\"returned\":int((g.followup_status==1).sum()),\"n\":len(q),\"wN\":sum(w),\"ESS\":sum(w)**2/sum(w*w),\"pre\":100*np.average(pre,weights=w),\"post\":100*np.average(post,weights=w),\"change\":100*m,\"var\":var}
def test(est,var):
 se=100*math.sqrt(var);return {\"estimate\":est,\"SE\":se,\"CI\":[est-1.959963984540054*se,est+1.959963984540054*se],\"p\":math.erfc(abs(est/se)/math.sqrt(2))}
def holm(ts):
 s=sorted(range(len(ts)),key=lambda i:ts[i][\"p\"]);a=0
 for j,i in enumerate(s):a=max(a,min(1,(len(ts)-j)*ts[i][\"p\"]));ts[i][\"holm\"]=a
primary={};het={};waves={};pairs={}
for k in [\"awareness\",\"consideration\",\"usage\"]:
 cells=[cell(d[d.assignment==a],k) for a in [0,1]]
 t=test(cells[1][\"change\"]-cells[0][\"change\"],sum(c[\"var\"] for c in cells))
 primary[k]={\"cells\":cells,\"test\":t}
 h=[cell(d[(d.children_under18==c)&(d.assignment==a)],k) for c in [0,1] for a in [0,1]]
 con=[test(h[i+1][\"change\"]-h[i][\"change\"],h[i+1][\"var\"]+h[i][\"var\"]) for i in [0,2]]
 het[k]={\"cells\":h,\"contrasts\":con,\"interaction\":test(con[1][\"estimate\"]-con[0][\"estimate\"],sum(c[\"var\"] for c in h))}
 waves[k]={str(a):{wave:dist(d[(d.assignment==a)&((d.followup_status==1) if wave==\"post\" else True)],k+\"_\"+wave) for wave in [\"pre\",\"post\"]} for a in [0,1]}
 pairs[k]={str(a):{wave:dist(d[(d.assignment==a)&(d.followup_status==1)&d[k+\"_pre\"].isin(v[k+\"_pre\"])&d[k+\"_post\"].isin(v[k+\"_post\"])],k+\"_\"+wave) for wave in [\"pre\",\"post\"]} for a in [0,1]}
holm([x[\"test\"] for x in primary.values()]);holm([x[\"interaction\"] for x in het.values()])
out={\"primary\":primary,\"heterogeneity\":het,\"waves\":waves,\"paired_distributions\":pairs}
out[\"attrition\"]={str(a):dist(d[d.assignment==a],\"followup_status\") for a in [0,1]}
out[\"profiles\"]={str(r):{k:dist(d[d.followup_status==r],k) for k in [\"awareness_pre\",\"consideration_pre\",\"usage_pre\",\"children_under18\",\"digital_confidence_pre\",\"budget_pressure_pre\"]} for r in [0,1]}
out[\"balance\"]={str(a)+\"_\"+str(r):{k:dist(d[(d.assignment==a)&((d.followup_status==1) if r else True)],k) for k in [\"awareness_pre\",\"consideration_pre\",\"usage_pre\",\"children_under18\",\"digital_confidence_pre\",\"budget_pressure_pre\"]} for a in [0,1] for r in [0,1]}
out[\"receipt\"]={str(a):dist(d[d.assignment==a],\"receipt_log\") for a in [0,1]}
out[\"recall\"]={str(a):dist(d[(d.assignment==a)&(d.followup_status==1)],\"recall_post\") for a in [0,1]}
out[\"concordance\"]={str(a):dist(d[(d.receipt_log==a)&(d.followup_status==1)],\"recall_post\") for a in [0,1]}
q=d[(d.followup_status==1)&d.consideration_pre.isin(v[\"consideration_pre\"])&d.consideration_post.isin(v[\"consideration_post\"])]
out[\"selection\"]={k:{str(a):{wave:dist(q[q[k]==a],\"consideration_\"+wave) for wave in [\"pre\",\"post\"]} for a in [0,1]} for k in [\"receipt_log\",\"recall_post\"]}
out[\"stress\"]={str(c):dist(d[d.children_under18==c],\"meal_stress_pre\") for c in [0,1]}
out[\"message\"]={k:dist(d[(d.followup_status==1)&(d.recall_post==1)],k) for k in [\"campaign_clear_post\",\"campaign_relevant_post\",\"campaign_trust_post\"]}
out[\"experience\"]={k:dist(d[(d.followup_status==1)&(d.usage_post==1)],k) for k in [\"usage_days_post\",\"satisfaction_post\"]}
out[\"correlations\"]={}
ks=list(out[\"message\"])
for i in range(3):
 for j in range(i+1,3):
  x,y=ks[i],ks[j];g=d[(d.followup_status==1)&(d.recall_post==1)&d[x].isin(v[x])&d[y].isin(v[y])];w=g.weight_base;a=g[x]-np.average(g[x],weights=w);b=g[y]-np.average(g[y],weights=w)
  out[\"correlations\"][x+\"_\"+y]=[len(g),sum(w),sum(w)**2/sum(w*w),sum(w*a*b)/math.sqrt(sum(w*a*a)*sum(w*b*b))]
s=d[(d.age_band==4)&(d.online_grocery_pre==1)&d.digital_confidence_pre.isin([4,5])]
out[\"small\"]={k:[int(((s.assignment==a)&(s.followup_status==1)&s[k+\"_pre\"].isin(v[k+\"_pre\"])&s[k+\"_post\"].isin(v[k+\"_post\"])).sum()) for a in [0,1]] for k in primary}
out[\"checks\"]={\"duplicate_ids\":int(d.respondent_id.duplicated().sum()),\"nonreturn_post_nonblanks\":int(d.loc[d.followup_status==0,[k for k in d if k.endswith(\"_post\")]].notna().sum().sum()),\"log_count_inconsistency\":int(((d.receipt_log==1)"'!=(d.receipt_count>0)).sum())}
print(json.dumps(out,default=float))
'"'"

